package com.example.pulseworkout.ui.theme

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Иконки дизайн-системы SilverGains (страница Components → Icons в Figma), экспортированы как SVG 24×24.
 * Цвет задаётся через `tint` у `Icon`, поэтому заливка здесь чёрная.
 */
object DsIcons {
    private fun icon(name: String, vararg paths: Pair<String, Boolean>): ImageVector {
        val b = ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f)
        paths.forEach { (d, evenOdd) ->
            b.addPath(
                PathParser().parsePathString(d).toNodes(),
                pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = SolidColor(Color.Black),
            )
        }
        return b.build()
    }

